# NutriSole G9 Stage H, H2 close-up identity classifier, ATTEMPT 2 of 2 (prereg docs/cv/gauntlet/G9_stageH_prereg.md; arch/classes unchanged).
# v2 changes vs v1 (failed: onnxscript missing -> no weights; ~85 min recursive globbing; untriaged Commons labels):
#  - Commons H-train / H-val labels from the agent triage (I/W -> class, N -> unknown, rest excluded); Commons oversampled (40% of draws)
#  - bounded directory discovery (no recursive glob); per-stage timing
#  - state_dict saved (.pt) BEFORE ONNX export; legacy exporter (dynamo=False) with onnxscript pip-installed as a fallback
# Free Kaggle only (T4 if free). No YOLO training.
import json, os, random, subprocess, sys, time
t0 = time.time()
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "imagehash", "onnx", "onnxscript"], check=False)
import numpy as np, torch, torch.nn as nn, timm, imagehash
from PIL import Image
BLOB_B64 = ""
W = "/kaggle/working"; random.seed(0); np.random.seed(0); torch.manual_seed(0)
C = ["banana", "apple", "mango", "citrus", "guava", "pomegranate", "lemon_lime", "tomato", "potato", "cucumber", "carrot", "capsicum", "unknown"]
CI = {c: i for i, c in enumerate(C)}
rep = dict(classes=C, attempt=2, notes=[], stage_s={})
def stage(n): rep["stage_s"][n] = round(time.time() - t0); print("STAGE", n, rep["stage_s"][n], flush=True)
stage("pip")
import base64, zlib, urllib.request
BLOB = json.loads(zlib.decompress(base64.b64decode(BLOB_B64)))
meta = BLOB["meta"]; HD = "/tmp/hset"; os.makedirs(f"{HD}/img", exist_ok=True)
evarr = np.array([np.packbits(imagehash.hex_to_hash(h).hash.flatten()) for h in BLOB["eval_hashes"]], dtype=np.uint8)
def near_eval(img):
    h = np.packbits(imagehash.phash(img).hash.flatten())
    return int(np.unpackbits(evarr ^ h, axis=1).sum(1).min()) <= 10
UA = {"User-Agent": "NutriSoleResearch/1.0 (clydara1@gmail.com)"}; wait = 0.5; got = 0; tdl = time.time()
for k, (lab, sp, url, code) in meta.items():
    if time.time() - tdl > 1200: break
    for a in range(3):
        try:
            open(f"{HD}/img/{k}.jpg", "wb").write(urllib.request.urlopen(urllib.request.Request(url, headers=UA), timeout=30).read()); got += 1; wait = max(0.4, wait * 0.9); break
        except Exception as e:
            if "429" in str(e): wait = min(20, wait * 2)
            time.sleep(wait)
    time.sleep(wait)
rep["commons_downloaded"] = got; rep["commons_listed"] = len(meta); stage("commons")
items = {"train": [], "val": []}
for k, (lab, sp, url, code) in meta.items():
    p = f"{HD}/img/{k}.jpg"
    if os.path.exists(p):
        try: Image.open(p).convert("RGB"); items[sp].append((p, CI[lab], "commons"))
        except Exception: pass
def subdirs(d):
    try: return sorted(e.path for e in os.scandir(d) if e.is_dir())
    except Exception: return []
def find_dirs(root, pred, maxdepth=4):  # BFS over directories only; never descends into a matched dir
    out, q = [], [(root, 0)]
    while q:
        d, dep = q.pop(0)
        if pred(d): out.append(d); continue
        if dep < maxdepth: q += [(x, dep + 1) for x in subdirs(d)]
    return out
def files_in(d, deep=False):
    ext = (".jpg", ".jpeg", ".png")
    if not deep: return sorted(e.path for e in os.scandir(d) if e.is_file() and e.name.lower().endswith(ext))
    out = []
    for r, _, fs in os.walk(d): out += [os.path.join(r, f) for f in fs if f.lower().endswith(ext)]
    return sorted(out)
inputs = subdirs("/kaggle/input"); inputs = inputs + [y for x in inputs for y in subdirs(x)] + [z for x in inputs for y in subdirs(x) for z in subdirs(y)]
def shallow(ds): return [d for d in ds if not any(d != e and d.startswith(e + "/") for e in ds)]
rep["inputs"] = inputs[:60]; print(inputs[:60], flush=True)
MAP = [("Apple", "apple"), ("Banana", "banana"), ("Mango", "mango"), ("Orange", "citrus"), ("Mandarine", "citrus"), ("Clementine", "citrus"),
       ("Tangelo", "citrus"), ("Lemon", "lemon_lime"), ("Limes", "lemon_lime"), ("Lime", "lemon_lime"), ("Guava", "guava"), ("Pomegranate", "pomegranate"),
       ("Tomato", "tomato"), ("Potato", "potato"), ("Cucumber", "cucumber"), ("Carrot", "carrot"), ("Pepper Red", "capsicum"), ("Pepper Green", "capsicum"),
       ("Pepper Yellow", "capsicum"), ("Pepper Orange", "capsicum")]
EXCL = ("Grapefruit", "Pomelo", "Pepper", "Cantaloupe", "Melon", "Watermelon", "Ginger", "Zucchini dark")
f360 = {}
fr_root = shallow([d for d in inputs if "fruit" in d.lower() and "recogn" in d.lower()])
veg_root = shallow([d for d in inputs if "vegetable" in d.lower()])
f_root = shallow([d for d in inputs if "fruit" in d.lower() and "recogn" not in d.lower() and "vegetable" not in d.lower()])
tr = [d for r in f_root for d in find_dirs(r, lambda d: os.path.basename(d) == "Training", 4) if "100x100" in d]
rep["f360_training_dirs"] = tr; print("f360", tr, flush=True)
if tr:
    r = tr[0]
    for d in subdirs(r):
        n = os.path.basename(d); lab = next((c for pre, c in MAP if n.startswith(pre)), None)
        if lab is None and n.startswith(EXCL): continue
        f360.setdefault(lab or "unknown", []).extend(files_in(d)[::3])
stage("f360_list")
FRMAP = {"apple": "apple", "banana": "banana", "guava": "guava", "mango": "mango", "orange": "citrus", "pomegranate": "pomegranate", "tomatoes": "tomato", "tomato": "tomato"}
for r in fr_root:
    cand = [r] + subdirs(r) + [y for x in subdirs(r) for y in subdirs(x)]
    best = max(cand, key=lambda d: sum(os.path.basename(x).lower() in FRMAP for x in subdirs(d)))
    rep["fr_root"] = best; print("fr", best, flush=True)
    for d in subdirs(best):
        fs = files_in(d, deep=True)
        if fs: f360.setdefault("fr:" + FRMAP.get(os.path.basename(d).lower(), "unknown"), []).extend(fs)
stage("fr_list")
VGMAP = {"capsicum": "capsicum", "carrot": "carrot", "cucumber": "cucumber", "potato": "potato", "tomato": "tomato"}
for r in veg_root:
    t = find_dirs(r, lambda d: os.path.basename(d).lower() == "train", 3); rep["veg_train"] = t; print("veg", t, flush=True)
    for d in subdirs(t[0]) if t else []:
        f360.setdefault("vg:" + VGMAP.get(os.path.basename(d).lower(), "unknown"), []).extend(files_in(d))
stage("veg_list")
print({k: len(v) for k, v in f360.items()}, flush=True)
CAPS = {"f360": 350, "fr": 450, "vg": 450}; UCAPS = {"f360": 1200, "fr": 1200, "vg": 900}
drop = 0; f360n = {}
for key, fs in f360.items():
    src, lab = key.split(":") if ":" in key else ("f360", key)
    cp = (UCAPS if lab == "unknown" else CAPS)[src] * (2 if lab == "lemon_lime" else 1)
    random.shuffle(fs); keep = []
    for f in fs[: int(cp * 1.2)]:
        try: im = Image.open(f).convert("RGB")
        except Exception: continue
        if near_eval(im): drop += 1; continue
        keep.append(f)
        if len(keep) >= cp: break
    f360n[f"{src}:{lab}"] = len(keep); items["train"] += [(f, CI[lab], src) for f in keep]
rep["kaggle_per_source_class"] = f360n; rep["kaggle_dropped_near_eval_or_ref"] = drop
rep["commons_train_near_eval"] = sum(1 for p, y, s in items["train"] if s == "commons" and near_eval(Image.open(p).convert("RGB")))
rep["train_per_class"] = {c: sum(1 for _, y, s in items["train"] if y == CI[c]) for c in C}
rep["commons_per_class"] = {c: sum(1 for _, y, s in items["train"] if y == CI[c] and s == "commons") for c in C}
rep["val_per_class"] = {c: sum(1 for _, y, _ in items["val"] if y == CI[c]) for c in C}
stage("audit"); print(json.dumps(rep), flush=True)
dev = "cuda" if torch.cuda.is_available() else "cpu"; rep["device"] = dev
import torchvision.transforms as T
MEAN, STD = (0.485, 0.456, 0.406), (0.229, 0.224, 0.225)
def white_bg_swap(img):
    a = np.asarray(img).astype(np.float32)
    if random.random() < 0.5:
        m = (a.min(2) > 235)[..., None]
        bg = np.random.uniform(30, 220, 3)[None, None] + np.random.normal(0, random.uniform(5, 40), a.shape)
        a = np.where(m, bg, a)
    return Image.fromarray(np.clip(a, 0, 255).astype(np.uint8))
tr_tf = T.Compose([T.RandomResizedCrop(224, scale=(0.3, 1.0), ratio=(0.7, 1.4)), T.RandomHorizontalFlip(), T.RandomRotation(25),
                   T.ColorJitter(0.35, 0.35, 0.25, 0.03), T.RandomGrayscale(0.02), T.ToTensor(), T.Normalize(MEAN, STD), T.RandomErasing(p=0.25, scale=(0.05, 0.25))])
va_tf = T.Compose([T.Resize(256), T.CenterCrop(224), T.ToTensor(), T.Normalize(MEAN, STD)])
class DS(torch.utils.data.Dataset):
    def __init__(s, it, tf): s.it, s.tf = it, tf
    def __len__(s): return len(s.it)
    def __getitem__(s, i):
        p, y, src = s.it[i]; im = Image.open(p).convert("RGB")
        if src == "f360" and s.tf is tr_tf: im = white_bg_swap(im.resize((160, 160)))
        elif src == "fr" and s.tf is tr_tf and random.random() < 0.5: im = white_bg_swap(im)
        return s.tf(im), y
# sampler: 40% of draws from Commons (class-balanced, class mass ~ min(n,15)), 60% from Kaggle sources (class-balanced)
ys = np.array([y for _, y, _ in items["train"]]); isc = np.array([s == "commons" for _, _, s in items["train"]])
wts = np.zeros(len(ys))
cc = np.bincount(ys[isc], minlength=len(C)); kc = np.bincount(ys[~isc], minlength=len(C))
cmass = np.minimum(cc, 15).astype(float); cmass = cmass / cmass.sum() * 0.40
kmass = (kc > 0).astype(float); kmass = kmass / kmass.sum() * 0.60
for i, (y, c) in enumerate(zip(ys, isc)): wts[i] = cmass[y] / cc[y] if c else kmass[y] / kc[y]
rep["sampler"] = dict(commons_share=0.40, commons_class_counts=cc.tolist(), kaggle_class_counts=kc.tolist())
NS = 9000
sampler = torch.utils.data.WeightedRandomSampler(wts, num_samples=NS, replacement=True)
tl = torch.utils.data.DataLoader(DS(items["train"], tr_tf), batch_size=64, sampler=sampler, num_workers=4, drop_last=True)
vl = torch.utils.data.DataLoader(DS(items["val"], va_tf), batch_size=128, num_workers=4)
model = timm.create_model("mobilenetv3_small_100", pretrained=True, num_classes=len(C)).to(dev)
EP = 18; opt = torch.optim.AdamW(model.parameters(), lr=1.5e-3, weight_decay=0.02)
sch = torch.optim.lr_scheduler.OneCycleLR(opt, max_lr=1.5e-3, total_steps=EP * len(tl), pct_start=0.15)
crit = nn.CrossEntropyLoss(label_smoothing=0.1); best = (-1, None); hist = []
def evaluate():
    model.eval(); P, Y = [], []
    with torch.no_grad():
        for x, y in vl: P.append(torch.softmax(model(x.to(dev)), 1).cpu().numpy()); Y.append(y.numpy())
    P, Y = np.concatenate(P), np.concatenate(Y); pr = P.argmax(1); sup = Y != CI["unknown"]
    return dict(acc=float((pr == Y).mean()), sup_acc=float((pr[sup] == Y[sup]).mean()), unk_recall=float((pr[~sup] == CI["unknown"]).mean()) if (~sup).any() else None,
                sup_to_unknown=float((pr[sup] == CI["unknown"]).mean()), bal=float(np.mean([(pr[Y == c] == c).mean() for c in range(len(C)) if (Y == c).any()])))
stage("train_start")
for ep in range(EP):
    model.train(); tl_sum = 0
    for x, y in tl:
        x, y = x.to(dev), y.to(dev); opt.zero_grad(); loss = crit(model(x), y); loss.backward(); opt.step(); sch.step(); tl_sum += loss.item()
    m = evaluate(); m.update(ep=ep, loss=tl_sum / len(tl), t=round(time.time() - t0)); hist.append(m); print(m, flush=True)
    if m["bal"] > best[0]: best = (m["bal"], {k: v.detach().clone() for k, v in model.state_dict().items()}, ep)
model.load_state_dict(best[1]); model.eval().cpu()
torch.save(model.state_dict(), f"{W}/h2_mnv3s.pt"); stage("pt_saved")
rep.update(history=hist, best_val_bal=best[0], best_ep=best[2], input="RGB 224 (resize short side 256 -> centre crop 224 at eval), ImageNet mean/std")
json.dump(rep, open(f"{W}/h2_report.json", "w"), indent=1)
class Wrap(nn.Module):
    def __init__(s, m): super().__init__(); s.m = m
    def forward(s, x): return torch.softmax(s.m(x), 1)
for kw in (dict(dynamo=False), dict()):
    try:
        torch.onnx.export(Wrap(model), torch.zeros(1, 3, 224, 224), f"{W}/h2_mnv3s.onnx", input_names=["images"], output_names=["probs"], opset_version=17,
                          dynamic_axes={"images": {0: "n"}, "probs": {0: "n"}}, **kw)
        rep["onnx_export"] = str(kw); break
    except Exception as e:
        rep["notes"].append(f"onnx export {kw} failed: {e!r}"[:400]); print("EXPORT FAIL", kw, e, flush=True)
rep["minutes"] = round((time.time() - t0) / 60, 1); stage("done")
json.dump(rep, open(f"{W}/h2_report.json", "w"), indent=1); print("DONE", rep["minutes"], flush=True)
